//simple_alloc 宿主行为测试，不参与裸机镜像

#include "simple_alloc.h"
#include "string_noalloc.h"

#define CHECK(condition)                                                       \
	do {                                                                   \
		if (!(condition))                                              \
			return __LINE__;                                       \
	} while (0)

static u8 arena[4096];

static i32 ptr_in_arena(void *p, usize n)
{
	usize base = (usize)arena;
	usize addr = (usize)p;
	usize end = base + sizeof(arena);

	if (p == NULL) {
		return 0;
	}
	if (addr < base || addr + n > end) {
		return 0;
	}
	return 1;
}

i32 main(void)
{
	void *a;
	void *b;
	void *c;
	void *d;
	void *e;
	usize i;

	CHECK(heap_init(arena, sizeof(arena)) == 0);
	CHECK(HEAP.start == arena);
	CHECK(HEAP.cap == sizeof(arena));
	CHECK(HEAP_ITEM_COUNT == 0);

	/* basic allocate / free */
	a = malloc(16);
	CHECK(ptr_in_arena(a, 16));
	CHECK(HEAP_ITEM_COUNT == 1);
	memset(a, 0xA5, 16);

	b = malloc(32);
	CHECK(ptr_in_arena(b, 32));
	CHECK(HEAP_ITEM_COUNT == 2);
	CHECK((usize)b >= (usize)a + 16);

	free(a);
	CHECK(HEAP_ITEM_COUNT == 1);

	/* reuse first gap (first-fit) */
	c = malloc(8);
	CHECK(c == a);
	CHECK(HEAP_ITEM_COUNT == 2);
	free(c);
	free(b);
	CHECK(HEAP_ITEM_COUNT == 0);

	/* coalesce left+right by removing middle used block */
	a = malloc(64);
	b = malloc(64);
	c = malloc(64);
	CHECK(HEAP_ITEM_COUNT == 3);
	free(a);
	free(c);
	CHECK(HEAP_ITEM_COUNT == 1);
	free(b);
	CHECK(HEAP_ITEM_COUNT == 0);

	/* coalesce enables larger reallocation */
	a = malloc(100);
	b = malloc(100);
	c = malloc(100);
	free(a);
	free(b);
	d = malloc(180);
	CHECK(d != NULL);
	CHECK(d == arena);
	free(d);
	free(c);
	CHECK(HEAP_ITEM_COUNT == 0);

	/* OOM on oversized request */
	CHECK(malloc(sizeof(arena) + 1) == NULL);

	/* fill table to capacity, next insert must fail */
	CHECK(heap_init(arena, sizeof(arena)) == 0);
	for (i = 0; i < (usize)SIMPLE_ALLOC_MAX_ITEMS; ++i) {
		e = malloc(SIMPLE_ALLOC_ALIGN);
		CHECK(e != NULL);
	}
	CHECK(HEAP_ITEM_COUNT == (usize)SIMPLE_ALLOC_MAX_ITEMS);
	CHECK(malloc(SIMPLE_ALLOC_ALIGN) == NULL);

	/* free one slot and allocate again */
	free((void *)((usize)arena));
	e = malloc(SIMPLE_ALLOC_ALIGN);
	CHECK(e != NULL);
	CHECK(HEAP_ITEM_COUNT == (usize)SIMPLE_ALLOC_MAX_ITEMS);

	/* free(NULL) is no-op */
	free(NULL);

	/* double-free / unknown pointer is ignored */
	free((void *)((usize)arena + 7u));
	CHECK(HEAP_ITEM_COUNT == (usize)SIMPLE_ALLOC_MAX_ITEMS);

	/* zero-size malloc fails */
	CHECK(malloc(0) == NULL);

	/* re-init clears metadata */
	CHECK(heap_init(arena, 128) == 0);
	CHECK(HEAP.cap == 128);
	CHECK(HEAP_ITEM_COUNT == 0);
	CHECK(malloc(64) != NULL);
	CHECK(malloc(128) == NULL);

	return 0;
}
